"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacyTaskRows from "../beautiful-ui/primitives/TaskRows";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type TaskRowsProps = NonNullable<ComponentProps<typeof LegacyTaskRows>>;

export const TaskRows = forwardRef<HTMLDivElement, TaskRowsProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacyTaskRows {...props} />
  </BeautifulUIRoot>
));

TaskRows.displayName = "TaskRows";

export default TaskRows;

"use client";

import "../beautiful-ui.css";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { springs } from "@/lib/springs";
import { useShape } from "@/lib/shape-context";
import { useReducedMotion } from "../hooks/useReducedMotion";

/* ─────────────────────────────────────────────────────────
 * TASK ROWS
 *
 *     0ms   rows enter staggered (80ms apart)
 *   600ms   row 1 ring sweeps 0 → 66%
 *  1500ms   row 1 expands — detail steps drop down
 *  3900ms   row 1 collapses; row 2 flips to Failed + retry
 *  5300ms   row 2 resolves to Completed
 * The status run completes once; task details stay clickable.
 * ───────────────────────────────────────────────────────── */

const TICKS = [600, 900, 2400, 1400, 2400, 600];

function useTick(intervals: number[], reducedMotion: boolean) {
  const [tick, setTick] = useState(0);
  useEffect(() => {
    if (reducedMotion) {
      setTick(intervals.length - 1);
      return;
    }
    if (tick >= intervals.length - 1) return;
    const t = setTimeout(() => setTick((x) => x + 1), intervals[tick]);
    return () => clearTimeout(t);
  }, [tick, intervals, reducedMotion]);
  return tick;
}

function SpinnerRing({ active, children }: { active?: boolean; children?: React.ReactNode }) {
  const size = 24,
    stroke = 2;
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  return (
    <span
      className="relative inline-flex shrink-0 items-center justify-center"
      style={{ width: size, height: size }}
    >
      <svg
        width={size}
        height={size}
        className="absolute inset-0"
        style={active ? { animation: "spin 1.1s linear infinite" } : undefined}
      >
        <circle
          cx={size / 2}
          cy={size / 2}
          r={r}
          fill="none"
          stroke="var(--line)"
          strokeWidth={stroke}
        />
        {active && (
          <circle
            cx={size / 2}
            cy={size / 2}
            r={r}
            fill="none"
            stroke="var(--ink-3)"
            strokeWidth={stroke}
            strokeLinecap="round"
            strokeDasharray={`${c * 0.28} ${c * 0.72}`}
          />
        )}
      </svg>
      <span className="relative text-[11px] font-semibold tabular-nums text-[var(--ink)]">
        {children}
      </span>
    </span>
  );
}

function Badge({
  tone,
  children,
  reducedMotion,
}: {
  tone: "red" | "green";
  children: React.ReactNode;
  reducedMotion: boolean;
}) {
  return (
    <span
      className={`flex size-5.5 shrink-0 items-center justify-center rounded-full text-[var(--background)]
        ${tone === "red" ? "bg-[var(--red)]" : "bg-[var(--green)]"}`}
      style={{
        animation: reducedMotion ? "none" : "pop-in 240ms cubic-bezier(0.23,1,0.32,1) both",
      }}
    >
      {children}
    </span>
  );
}

const XIcon = (
  <svg
    width="12"
    height="12"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="3.5"
    strokeLinecap="round"
  >
    <path d="M18 6L6 18M6 6l12 12" />
  </svg>
);
const CheckIcon = (
  <svg
    width="13"
    height="13"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="3.5"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M20 6L9 17l-5-5" />
  </svg>
);
const RetryIcon = (
  <svg
    width="12"
    height="12"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="3"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M21 12a9 9 0 1 1-2.64-6.36M21 3v6h-6" />
  </svg>
);

export type TaskRowStatus = "pending" | "working" | "failed" | "done";

export interface TaskRowsProps {
  variant?: string;
  demo?: boolean;
  onTaskToggle?: (taskKey: string, expanded: boolean) => void;
  onStatusChange?: (taskKey: string, status: TaskRowStatus) => void;
}

export default function TaskRows({
  variant = "Capsules",
  demo = false,
  onTaskToggle,
  onStatusChange,
}: TaskRowsProps) {
  const shape = useShape();
  const reducedMotion = useReducedMotion();
  const tick = useTick(TICKS, reducedMotion || !demo);
  const [manualOpen, setManualOpen] = useState<Record<string, boolean>>({});
  const indexStatus: TaskRowStatus = tick < 3 ? "working" : "done";
  const row2: TaskRowStatus = tick < 3 ? "pending" : tick === 3 ? "failed" : "done";
  const reportedStatusesRef = useRef<{
    verify?: TaskRowStatus;
    index?: TaskRowStatus;
    draft?: TaskRowStatus;
  }>({});

  useEffect(() => {
    if (reportedStatusesRef.current.verify !== "done") {
      reportedStatusesRef.current.verify = "done";
      onStatusChange?.("verify", "done");
    }
    if (reportedStatusesRef.current.index !== indexStatus) {
      reportedStatusesRef.current.index = indexStatus;
      onStatusChange?.("index", indexStatus);
    }
    if (reportedStatusesRef.current.draft !== row2) {
      reportedStatusesRef.current.draft = row2;
      onStatusChange?.("draft", row2);
    }
  }, [indexStatus, onStatusChange, row2]);

  const rows = [
    {
      key: "verify",
      badge: (
        <Badge tone="green" reducedMotion={reducedMotion}>
          {CheckIcon}
        </Badge>
      ),
      status: "done" as TaskRowStatus,
      label: "Verified vendor records",
      amount: "12 suppliers",
      pill: (
        <span
          className={`inline-flex h-5.5 items-center ${shape.item} bg-[var(--green-tint)] px-2 text-[12px] font-medium text-[var(--green)]`}
        >
          Completed
        </span>
      ),
      details: [
        { label: "Matched tax and contact IDs", meta: "12/12" },
        { label: "Flagged stale records", meta: "0" },
      ],
    },
    {
      key: "index",
      badge:
        indexStatus === "working" ? (
          <SpinnerRing active={!reducedMotion}>2</SpinnerRing>
        ) : (
          <Badge tone="green" reducedMotion={reducedMotion}>
            {CheckIcon}
          </Badge>
        ),
      status: indexStatus,
      label: "Build reorder task list",
      amount: "7 SKUs",
      pill: null,
      details: [
        { label: "Reading POS export", meta: "3 files" },
        { label: "Scoring stockout risk", meta: "68%" },
      ],
    },
    {
      key: "draft",
      badge:
        row2 === "pending" ? (
          <SpinnerRing>3</SpinnerRing>
        ) : row2 === "failed" ? (
          <Badge tone="red" reducedMotion={reducedMotion}>
            {XIcon}
          </Badge>
        ) : (
          <Badge tone="green" reducedMotion={reducedMotion}>
            {CheckIcon}
          </Badge>
        ),
      status: row2,
      label: "Draft supplier emails",
      amount: "2 messages",
      pill:
        row2 === "failed" ? (
          <span
            className={`inline-flex h-5.5 items-center gap-1.5 ${shape.item} bg-[var(--red-tint)] px-2 text-[12px] font-medium text-[var(--red)]`}
            style={{ animation: reducedMotion ? "none" : "fade-in 160ms ease-out both" }}
          >
            Failed{" "}
            <span
              style={{ animation: reducedMotion ? "none" : "spin 1.2s linear infinite" }}
              className="flex"
            >
              {RetryIcon}
            </span>
          </span>
        ) : row2 === "done" ? (
          <span
            className={`inline-flex h-5.5 items-center gap-1.5 ${shape.item} bg-[var(--green-tint)] px-2 text-[12px] font-medium text-[var(--green)]`}
            style={{ animation: reducedMotion ? "none" : "fade-in 160ms ease-out both" }}
          >
            Completed
          </span>
        ) : null,
      details: [
        { label: "Cone supplier follow-up", meta: "draft" },
        { label: "Pistachio reorder note", meta: "draft" },
      ],
    },
  ];

  const list = variant === "List";
  return (
    <div
      className={`flex w-full max-w-110 flex-col ${
        list
          ? `gap-0 self-start overflow-hidden ${shape.container} bg-[var(--surface)] shadow-[var(--shadow-card)]`
          : "min-h-[196px] gap-2"
      }`}
    >
      <span className="sr-only" role="status" aria-live="polite" aria-atomic="true">
        {row2 === "failed"
          ? "Draft supplier emails failed"
          : row2 === "done"
            ? "Draft supplier emails completed"
            : ""}
      </span>
      {rows.map((row, i) => {
        const open = manualOpen[row.key] ?? (row.key === "index" && tick === 2);
        return (
          <div
            key={row.key}
            className={`self-stretch overflow-hidden transition-[border-radius,background-color] duration-240 hover:bg-[var(--inset)] ${
              list
                ? "border-b border-[var(--line)] last:border-0"
                : "bg-[var(--surface)] shadow-[var(--shadow-card)]"
            }`}
            style={{
              borderRadius: list ? 0 : shape.containerRadius,
              animation: reducedMotion
                ? "none"
                : `fade-up 240ms cubic-bezier(0.23,1,0.32,1) ${i * 80}ms both`,
            }}
          >
            <button
              type="button"
              aria-expanded={open}
              aria-label={`${open ? "Collapse" : "Expand"} ${row.label}, status ${row.status}`}
              onClick={() => {
                const next = !open;
                setManualOpen((current) => ({ ...current, [row.key]: next }));
                onTaskToggle?.(row.key, next);
              }}
              className={`flex h-11 w-full items-center gap-2.5 ${list ? "rounded-none" : shape.container} px-2.5 text-left transition-transform duration-80 active:scale-[0.98]`}
            >
              <span className="flex size-6 shrink-0 items-center justify-center">{row.badge}</span>
              <span className="min-w-0 flex-1 truncate text-[13px] font-medium text-[var(--ink)]">
                {row.label}
              </span>
              <span className="text-[13px] text-[var(--ink-2)] tabular-nums">{row.amount}</span>
              {row.pill}
              <span
                aria-hidden="true"
                className="-ml-2 flex size-7 shrink-0 items-center justify-center rounded-full text-[var(--ink-3)]"
              >
                <svg
                  width="15"
                  height="15"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2.2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  className="transition-transform duration-160"
                  style={{ transform: open ? "rotate(180deg)" : "rotate(0)" }}
                >
                  <path d="M6 9l6 6 6-6" />
                </svg>
              </span>
            </button>

            {/* dropdown detail — same expandable grammar as Chain of Thought */}
            <AnimatePresence initial={false}>
              {open && (
                <motion.div
                  initial={reducedMotion ? false : { height: 0, opacity: 0 }}
                  animate={{ height: "auto", opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  transition={reducedMotion ? { duration: 0 } : springs.slow}
                  className="overflow-hidden"
                >
                  <div className="mb-2.5 grid grid-cols-[24px_1fr] gap-2.5 px-2.5">
                    <span aria-hidden className="mx-auto h-full w-px bg-[var(--line)]" />
                    <div className="flex flex-col gap-1.5">
                      {row.details.map((d, j) => (
                        <div
                          key={d.label}
                          className="flex items-center justify-between"
                          style={
                            reducedMotion
                              ? undefined
                              : {
                                  animation: `fade-up 240ms cubic-bezier(0.23,1,0.32,1) ${80 + j * 80}ms both`,
                                }
                          }
                        >
                          <span className="text-[12px] text-[var(--ink-2)]">{d.label}</span>
                          <span className="font-mono text-[12px] text-[var(--ink-3)] tabular-nums">
                            {d.meta}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import "./beautiful-ui.css";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { useShapeVariant } from "@/lib/shape-context";

export type BeautifulUIRootProps = HTMLAttributes<HTMLDivElement>;

type AdapterStyle = CSSProperties & Record<`--${string}`, string | number>;

function clampSurface(level: number) {
  return Math.max(1, Math.min(8, level));
}

function createAdapterStyle(
  substrate: number,
  surface: number,
  style?: CSSProperties,
): AdapterStyle {
  const inset = clampSurface(substrate + 1);
  const overlay = clampSurface(surface + 2);
  const raisedOverlay = clampSurface(surface + 4);

  return {
    "--page": `var(--surface-${substrate})`,
    "--canvas": `var(--surface-${substrate})`,
    "--surface": `var(--surface-${surface})`,
    "--inset": `var(--surface-${inset})`,
    "--tooltip-bg": `var(--surface-${overlay})`,
    "--overlay-surface": `var(--surface-${overlay})`,
    "--overlay-raised": `var(--surface-${raisedOverlay})`,
    ...style,
  };
}

function useBeautifulUIScope(offset = 2) {
  const substrate = useSurface();
  const surface = clampSurface(substrate + offset);
  const shape = useShapeVariant();

  return {
    shape,
    substrate,
    surface,
    style: createAdapterStyle(substrate, surface),
  };
}

/**
 * Internal compatibility boundary for the adapted primitives. It has no layout
 * box of its own: public components use it internally so consumers inherit the
 * active BoringUI theme, surface level, and radius mode without a wrapper.
 */
export const BeautifulUIRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", "contents", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIRoot.displayName = "BeautifulUIRoot";

/** Applies the same BoringUI scope to content rendered in a body portal. */
export const BeautifulUIPortalRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIPortalRoot.displayName = "BeautifulUIPortalRoot";

export default BeautifulUIRoot;

